	/**
	 * Default Constructor
	 */
    public UsageLimitService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new UsageLimitEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(UsageLimitRepository.class) );
		this.validator		= applicationContext.getBean(UsageLimitValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		UsageLimit
	 */
		public UsageLimit createUsageLimit( CreateUsageLimitCommand command ) {

		UsageLimit entity = new UsageLimit();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setUsageLimitId( command.getUsageLimitId() );
            entity.setName( command.getName() );
            entity.setAmount( command.getAmount() );
            entity.setCount( command.getCount() );
            entity.setScope( command.getScope() );
            entity.setPeriod( command.getPeriod() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of UsageLimit {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateUsageLimitCommand
	 * @return		UsageLimit
	 */
	public UsageLimit updateUsageLimit( UpdateUsageLimitCommand command ) {

		UsageLimit entity = new UsageLimit();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setUsageLimitId( command.getUsageLimitId() );
            entity.setName( command.getName() );
            entity.setAmount( command.getAmount() );
            entity.setCount( command.getCount() );
            entity.setPricingPlan( command.getPricingPlan() );
            entity.setScope( command.getScope() );
            entity.setPeriod( command.getPeriod() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of UsageLimit {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteUsageLimitCommand
	 */
	public void delete( DeleteUsageLimitCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getUsageLimitId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of UsageLimit {0} ", id );

	}

	/**
	 * Method to retrieve the UsageLimit via UsageLimitFetchOneSummary
	 * @param 	summary UsageLimitFetchOneSummary
	 * @return 	UsageLimitFetchOneResponse
	 */
	public UsageLimit getUsageLimit( UsageLimitFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "UsageLimitFetchOneSummary arg cannot be null" );

		UsageLimit entity = null;
		UUID id = summary.getUsageLimitId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a UsageLimit using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all UsageLimits
	 *
	 * @return 	List<UsageLimit>
	 */
    public List<UsageLimit> getAllUsageLimit() {
		List<UsageLimit> list = projector.findAll( new FindAllUsageLimitQuery() );
		return list;
	}

	/**
	 * assign PricingPlan on UsageLimit
	 * @param		command AssignPricingPlanToUsageLimitCommand
	 */
	public void assignPricingPlan( AssignPricingPlanToUsageLimitCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPricingPlan(command.getUsageLimitId(), command.getAssignment());

	}

	/**
	 * unAssign PricingPlan on UsageLimit
	 * @param		command UnAssignPricingPlanFromUsageLimitCommand
	 */
	public void unAssignPricingPlan( UnAssignPricingPlanFromUsageLimitCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignPricingPlan(command.getUsageLimitId());
	}
	




